def test_zero_row_dataframe_with_explicit_band_range():
    """A 0-row DataFrame with an explicit banded axis must not panic; if it
    renders, the SVG viewBox and coordinates are finite.

    Targets distinct_positional_categories on an empty batch feeding
    OrdinalScale::new_internal with an empty domain (layout divides by n == 0).
    """
    df = pl.DataFrame(schema={"cat": pl.Utf8, "val": pl.Float64})
    chart = (
        fr.Chart(df)
        .mark_bar()
        .encode(
            x=fr.X("cat", scale=fr.BandScale(range=[40.0, 260.0])),
            y="val",
        )
        .properties(width=600, height=400)
    )
    try:
        svg = chart.to_svg()
    except ValueError:
        return  # a typed refusal is acceptable for empty data
    except BaseException as e:  # pyo3 PanicException is a BaseException
        pytest.fail(f"0-row render must not panic: {type(e).__name__}: {e}")
    _assert_finite_svg(svg)
    assert "viewBox" in svg or "<svg" in svg


def test_ordinal_scale_mixed_numeric_string_range_positional():
    """OrdinalScale(range=[40.0, '#ccc', 260.0]) on x: the positional resolver
    extracts the numbers ([40, 260]) and treats them as an explicit range.

    Targets ordinal_pixel_range's mixed-entry path (OrdinalRangeValue::numbers
    dropping the string) — only pure-numeric ranges are covered elsewhere.
    """
    df = pl.DataFrame({"cat": ["a", "b"], "val": [1.0, 2.0]})
    svg = (
        fr.Chart(df)
        .mark_bar()
        .encode(
            x=fr.X(
                "cat",
                scale=fr.OrdinalScale(domain=["a", "b"], range=[40.0, "#cccccc", 260.0]),
            ),
            y="val",
        )
        .properties(width=600, height=400)
        .to_svg()
    )
    _assert_finite_svg(svg)
    bars = _data_bar_rects(svg)
    assert len(bars) == 2
    for a in bars:
        x0 = float(a["x"])
        x1 = x0 + float(a["width"])
        assert 40.0 - 0.5 <= x0 and x1 <= 260.0 + 0.5, (
            f"bar [{x0}, {x1}] ignores the numeric entries of the mixed range: {a!r}"
        )


def test_integer_range_values_accepted_via_pyo3_coercion():
    """range=[40, 260] (Python ints) coerces to f64 across PyO3 and behaves
    identically to the float form.

    Targets the Vec<f64> extraction in scale/band.rs::new.
    """
    df = pl.DataFrame({"cat": ["a", "b"], "val": [1.0, 2.0]})

    def render(range_) -> str:
        return (
            fr.Chart(df)
            .mark_bar()
            .encode(x=fr.X("cat", scale=fr.BandScale(domain=["a", "b"], range=range_)), y="val")
            .properties(width=600, height=400)
            .to_svg()
        )

    assert render([40, 260]) == render([40.0, 260.0])


