# Diverging on positional channels (GH #40)
# ---------------------------------------------------------------------------


def test_diverging_three_element_domain_positional_keeps_full_extent():
    """DivergingScale(domain=[-10, 0, 10]) on x: the point at x = 10 must
    render (domain NOT truncated to [-10, 0], the #40 regression).

    Targets ScaleSpec::positional_extent's Diverging arm (first/last element).
    """
    df = pl.DataFrame({"x": [-10.0, 0.0, 10.0], "y": [1.0, 2.0, 3.0]})
    svg = (
        fr.Chart(df)
        .mark_point()
        .encode(
            x=fr.X("x", scale=fr.DivergingScale(scheme="rdbu", domain=[-10.0, 0.0, 10.0])),
            y="y",
        )
        .properties(width=600, height=400)
        .to_svg()
    )
    _assert_finite_svg(svg)
    cxs = _circle_cxs(svg)
    assert len(cxs) == 3, (
        f"all 3 points must survive a [-10, 0, 10] diverging positional domain "
        f"(truncation to [lo, mid] drops x=10); got {len(cxs)}: {cxs}"
    )
    # The three points are evenly spaced under a linear [-10, 10] extent.
    assert cxs[1] - cxs[0] == pytest.approx(cxs[2] - cxs[1], abs=1.0), (
        f"points not evenly spaced — extent likely wrong: {cxs}"
    )


def test_diverging_two_element_domain_positional_matches_three_element():
    """DivergingScale(domain=[-10, 10]) (midpoint auto-inserted) resolves the
    same positional extent as the explicit [-10, 0, 10] form.

    Targets the 2-element expansion in scale/diverging.rs::new composed with
    positional_extent (both should yield [lo, hi] = [-10, 10]).
    """
    df = pl.DataFrame({"x": [-10.0, 0.0, 10.0], "y": [1.0, 2.0, 3.0]})

    def render(domain: list[float]) -> str:
        return (
            fr.Chart(df)
            .mark_point()
            .encode(x=fr.X("x", scale=fr.DivergingScale(scheme="rdbu", domain=domain)), y="y")
            .properties(width=600, height=400)
            .to_svg()
        )

    cx2 = _circle_cxs(render([-10.0, 10.0]))
    cx3 = _circle_cxs(render([-10.0, 0.0, 10.0]))
    assert len(cx2) == 3 and len(cx3) == 3
    assert cx2 == pytest.approx(cx3, abs=0.5), (
        f"2-element and 3-element diverging domains must resolve the same "
        f"positional extent: {cx2} vs {cx3}"
    )


def test_diverging_asymmetric_midpoint_does_not_shift_positions():
    """A skewed midpoint ([-10, 8, 10]) affects color only; positional pixels
    are identical to the symmetric-midpoint render.

    Targets the doc contract in scale/diverging.rs ('the midpoint only affects
    color mapping') through positional_extent's first/last-element extraction.
    """
    df = pl.DataFrame({"x": [-10.0, 0.0, 10.0], "y": [1.0, 2.0, 3.0]})

    def cxs(domain: list[float]) -> list[float]:
        svg = (
            fr.Chart(df)
            .mark_point()
            .encode(x=fr.X("x", scale=fr.DivergingScale(scheme="rdbu", domain=domain)), y="y")
            .properties(width=600, height=400)
            .to_svg()
        )
        return _circle_cxs(svg)

    assert cxs([-10.0, 8.0, 10.0]) == pytest.approx(cxs([-10.0, 0.0, 10.0]), abs=0.5)


