# Wire round-trips
# ---------------------------------------------------------------------------


def test_band_point_specs_survive_chartspec_json_round_trip():
    """Band range / Point reverse+range survive ChartSpec.from_json(to_json()).

    Targets the serde field definitions of ScaleSpec::Band / ScaleSpec::Point
    in spec/encoding.rs — a skipped or defaulted field silently reverts the
    #39/#65 fixes on any spec that round-trips through JSON.
    """
    from ferrum._core import ChartSpec

    df = pl.DataFrame({"cat": ["a", "b"], "val": [1.0, 2.0]})
    chart = (
        fr.Chart(df)
        .mark_point()
        .encode(
            x=fr.X(
                "cat", scale=fr.PointScale(domain=["a", "b"], reverse=True, range=[40.0, 260.0])
            ),
            y="val",
        )
    )
    wire = chart.to_json()
    round_tripped = json.loads(ChartSpec.from_json(wire).to_json())
    x_scale = round_tripped["encoding"]["x"]["scale"]
    assert x_scale.get("type") == "point"
    assert x_scale.get("range") == [40.0, 260.0], f"range lost in round trip: {x_scale!r}"
    assert x_scale.get("reverse") is True, f"reverse lost in round trip: {x_scale!r}"

    band_chart = (
        fr.Chart(df)
        .mark_bar()
        .encode(
            x=fr.X("cat", scale=fr.BandScale(domain=["a", "b"], range=[260.0, 40.0])),
            y="val",
        )
    )
    band_rt = json.loads(ChartSpec.from_json(band_chart.to_json()).to_json())
    b_scale = band_rt["encoding"]["x"]["scale"]
    assert b_scale.get("type") == "band"
    assert b_scale.get("range") == [260.0, 40.0], (
        f"inverted band range lost/reordered in round trip: {b_scale!r}"
    )


def test_point_scale_getters_round_trip_all_fields():
    """PointScale getters report exactly what the constructor received.

    Targets the pyclass getters in scale/point.rs (domain/range/padding/
    align/reverse) for a fully-specified scale.
    """
    s = fr.PointScale(domain=["a", "b"], padding=0.25, align=1.0, reverse=True, range=[10.0, 90.0])
    assert s.domain == ["a", "b"]
    assert s.padding == 0.25
    assert s.align == 1.0
    assert s.reverse is True
    assert s.range == [10.0, 90.0]
    assert math.isnan(s.scale("zzz")), "unknown category must map to NaN"
